        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='reservation' GROUP BY ALL ORDER BY p", "claim": "The reservation service emits server spans in the normal period (about 524 CheckAvailability) and none at all in the abnormal period."},
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) n, sum(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) s5xx, round(approx_quantile(duration,0.5)/1e6,3) med_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability' GROUP BY ALL ORDER BY p", "claim": "Frontend CheckAvailability calls to reservation fail in about 0.01 ms in abnormal (vs 0.9 ms normal), with no reservation response."}
      ]
    },
    {
      "service": "search",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT p, metric, round(avg(value),3) avg_v, round(max(value),3) max_v, count(*) n FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE attr_k8s_pod_name='search-86857cbc94-xsvlq' AND metric IN ('k8s.pod.cpu.usage','container.cpu.usage') GROUP BY ALL ORDER BY metric, p", "claim": "Search pod CPU rises from about 0.006 cores to a flat ceiling near 2.5 cores in the abnormal window."},
        {"kind": "trace", "sql": "SELECT p, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,3) med_ms, round(approx_quantile(duration,0.95)/1e6,3) p95ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='search' AND span_name='search.Search/Nearby' GROUP BY ALL ORDER BY p", "claim": "Search server span median rises from about 2.3 ms to 3.5 ms in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {"from": "reservation", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT p, span_name, count(*) n, sum(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) s5xx, round(approx_quantile(duration,0.5)/1e6,3) med_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='frontend' AND span_name='reservation.Reservation/CheckAvailability') GROUP BY ALL ORDER BY span_name, p", "claim": "All 718 frontend HTTP /hotels requests return 5xx in abnormal, while the reservation check fails immediately beforehand."}]},
    {"from": "search", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT p, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,3) med_ms, round(approx_quantile(duration,0.95)/1e6,3) p95ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client' GROUP BY ALL ORDER BY p", "claim": "Frontend's calls to search slow from a median of 2.4 ms to 3.7 ms in the abnormal window."}]}
